  get object(): H.Ptr<R.Object>;
  set object(v: R.Object | null);
  /** UV map to use for mapping with UV texture coordinates Default: "". */
  get uv_layer(): H.Ref<string>;
  set uv_layer(v: H.In<string>);
  /**
   * X Mapping Default: 'X'.
   * - `NONE`: None
   * - `X`: X
   * - `Y`: Y
   * - `Z`: Z
   */
  get mapping_x(): H.Ref<"NONE" | "X" | "Y" | "Z">;
  set mapping_x(v: H.In<"NONE" | "X" | "Y" | "Z">);
