  set mapping_y(v: H.In<"NONE" | "X" | "Y" | "Z">);
  /**
   * Z Mapping Default: 'Z'.
   * - `NONE`: None
   * - `X`: X
   * - `Y`: Y
   * - `Z`: Z
   */
  get mapping_z(): H.Ref<"NONE" | "X" | "Y" | "Z">;
  set mapping_z(v: H.In<"NONE" | "X" | "Y" | "Z">);
