  get ndof_orbit_center_selected(): H.Ref<boolean>;
  set ndof_orbit_center_selected(v: H.In<boolean>);
  /** Invert Pitch (X) Axis Default: False. */
  get ndof_rotx_invert_axis(): H.Ref<boolean>;
