  get memory_cache_limit(): H.Ref<number>;
  set memory_cache_limit(v: H.In<number>);
  /** Approximate maximum size of the call stack used by Geometry Nodes. For example, this corresponds to the number of allowed nested node groups. Setting this too high can result in crashes caused by running out of stack memory. Range: 1 to 2147483647. Default: 100. */
  get geometry_nodes_stack_limit(): H.Ref<number>;
  set geometry_nodes_stack_limit(v: H.In<number>);
  /**
   * When and how proxies are created Default: 'AUTOMATIC'.
   * - `MANUAL`: Manual (Set up proxies manually)
   * - `AUTOMATIC`: Automatic (Build proxies for added movie and image strips in each preview size)
   */
  get sequencer_proxy_setup(): H.Ref<"MANUAL" | "AUTOMATIC">;
  set sequencer_proxy_setup(v: H.In<"MANUAL" | "AUTOMATIC">);
  /** Maximum number of lines to store for the console buffer Range: 32 to 32768. Default: 256. */
  get scrollback(): H.Ref<number>;
